-- claim. Each pause is one row; resumed_on is null while the plan is still paused.
CREATE TABLE person_plan_pause (
    plan_id    BIGINT NOT NULL REFERENCES person_plan (id) ON DELETE CASCADE,
    paused_on  DATE   NOT NULL,
    resumed_on DATE
);
